// Generates the CSS variables and the Tailwind theme from design/tokens.json.
// tokens.json is the single source; never edit the generated files by hand.
//
//   node scripts/build-tokens.mjs
//
// Writes:
//   src/styles/tokens.css          CSS variables (--gc-*), dark as default, light via data-theme
//   src/styles/theme.css           Tailwind 4 theme (@theme inline), maps roles to utilities

import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const tokens = JSON.parse(readFileSync(resolve(root, "design/tokens.json"), "utf8"));

const HEADER = "/* Generated by scripts/build-tokens.mjs from design/tokens.json. Do not edit by hand. */\n";
const px = (n) => (n === 0 ? "0" : `${n}px`);

const themes = Object.keys(tokens.color);
const roles = Object.keys(tokens.color.dark);
for (const theme of themes) {
  const missing = roles.filter((r) => !(r in tokens.color[theme]));
  const extra = Object.keys(tokens.color[theme]).filter((r) => !roles.includes(r));
  if (missing.length || extra.length) {
    throw new Error(`Theme "${theme}" does not match "dark": missing [${missing}], extra [${extra}]`);
  }
}

const colorVars = (theme) =>
  roles.map((role) => `  --gc-${role}: ${tokens.color[theme][role]};`).join("\n");

const shared = [
  `  --gc-font-sans: ${tokens.font.sans};`,
  `  --gc-font-mono: ${tokens.font.mono};`,
  ...Object.entries(tokens.radius).map(([k, v]) => `  --gc-radius-${k}: ${px(v)};`),
  ...Object.entries(tokens.shadow).map(([k, v]) => `  --gc-shadow-${k}: ${v};`),
  ...Object.entries(tokens.motion).map(([k, v]) => `  --gc-motion-${k}: ${v};`),
  ...Object.entries(tokens.size).map(([k, v]) => `  --gc-size-${k}: ${px(v)};`),
].join("\n");

const tokensCss = `${HEADER}
:root {
  color-scheme: dark;
${colorVars("dark")}

${shared}
}

:root[data-theme="light"] {
  color-scheme: light;
${colorVars("light")}
}
`;

// Tailwind's default palette, radii and shadows are removed so components can only use
// roles (bg-surface, text-text-muted), never raw colours.
const themeCss = `${HEADER}
@theme inline {
  --color-*: initial;
  --color-transparent: transparent;
  --color-current: currentColor;
${roles.map((role) => `  --color-${role}: var(--gc-${role});`).join("\n")}

  --font-sans: var(--gc-font-sans);
  --font-mono: var(--gc-font-mono);

  --text-*: initial;
${Object.entries(tokens.type)
  .map(([k, v]) => `  --text-${k}: ${px(v.size)};\n  --text-${k}--line-height: ${px(v.line)};`)
  .join("\n")}

  --radius-*: initial;
${Object.keys(tokens.radius).map((k) => `  --radius-${k}: var(--gc-radius-${k});`).join("\n")}

  --shadow-*: initial;
${Object.keys(tokens.shadow).map((k) => `  --shadow-${k}: var(--gc-shadow-${k});`).join("\n")}

  --spacing: 4px;
${Object.keys(tokens.size).map((k) => `  --spacing-${k}: var(--gc-size-${k});`).join("\n")}

  --ease-out: var(--gc-motion-ease);
  --default-transition-duration: var(--gc-motion-fast);
  --default-transition-timing-function: var(--gc-motion-ease);
}
`;

const outputs = {
  "src/styles/tokens.css": tokensCss,
  "src/styles/theme.css": themeCss,
};
for (const [file, content] of Object.entries(outputs)) {
  const target = resolve(root, file);
  mkdirSync(dirname(target), { recursive: true });
  writeFileSync(target, content);
  console.log("written:", file);
}
console.log(`${roles.length} colour roles × ${themes.length} themes`);
